 '<div class="kpis">'+[[d.seg,'seguidores'],[d.postsSem,'posts por semana'],[d.eng,'engajamento médio','%'],[d.nota,'nota no Google','★']].map(k=>'<div class="kpi"><b '+(Number.isInteger(k[0])?'data-count="'+k[0]+'" data-suf="'+(k[2]||'')+'">0':'>'+String(k[0]).replace('.',',')+(k[2]||''))+'</b><span class="sm">'+k[1]+'</span></div>').join('')+'</div>'+
 '<div class="tabs" role="tablist">'+[['geral','O que estão fazendo'],['posts','Posts'],['anuncios','Anúncios'],['site','Site'],['rebater','Como rebater'],['metas','Alcance e metas']].map(t=>'<button role="tab" aria-selected="'+(cTab===t[0])+'" data-ctab="'+t[0]+'">'+t[1]+'</button>').join('')+'</div><div id="ctab" class="view">';
